INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('hell-lord-doom', 'Hell Lord Doom', 'Vicious Blade, a Raksasha (true name Vinka Bisdemie)', 'Hell Lord of Hell Pit Calgary and General to Modeus', 'rifts', 'Raksasha (Greater Demon of Hades), posing as the Baal-Rog Hell Lord Doom', '8th Level Raksasha and 5th level Soulmancer (as printed)', 8, 'Diabolic', 'Effectively Immortal', 'Mutable, 1 to 20 feet (0.3 m to 6.1 m)', 'One ton at his maximum height', '{"IQ":21,"ME":19,"MA":23,"PS":40,"PP":17,"PE":26,"PB":8,"Spd":20}', 66, 70, 1100, 700, 600, 10, 16, '{"attacks":8,"initiative":4,"strike":5,"parry":5,"dodge":5,"disarm":2,"pull":4,"roll":4}', 'M.D.C. 1,100. Hit Points 66, S.D.C. 70 and A.R. 10 are the block''s figures for S.D.C. settings only. Saves as printed: +14 vs Horror Factor, +11 vs magic, +4 vs psionics, +4 vs pain, +2 vs possession, mind control and mind-controlling drugs; +1 to Spell Strength. Horror Factor 16 comes from Hell Lord Doom''s reputation alone. Supernatural P.S. 40. W.P. Sword, Knife, Staff and Chain. Considered a Master Psionic.', '[{"name":"Astronomy","pct":86},{"name":"Anthropology","pct":81},{"name":"Climbing","pct":91},{"name":"Computer Operation","pct":98},{"name":"Dance","pct":98},{"name":"Forgery","pct":86},{"name":"Horsemanship: General","pct":98},{"name":"Horsemanship: Exotic Animals","pct":91},{"name":"Intelligence","pct":96},{"name":"Land Navigation","pct":71},{"name":"Literacy: American","pct":98},{"name":"Literacy: Atlantean","pct":98},{"name":"Literacy: Demongogian","pct":98},{"name":"Literacy: Dragonese/Elven","pct":98},{"name":"Literacy: Euro","pct":98},{"name":"Literacy: Splugorth","pct":98},{"name":"Lore: Demons & Monsters","pct":98},{"name":"Lore: Faeries & Creatures of Magic","pct":98},{"name":"Mathematics: Advanced","pct":98},{"name":"Mathematics: Basic","pct":98},{"name":"Prowl","pct":71},{"name":"Radio: Basic","pct":98},{"name":"Seduction","pct":66},{"name":"Sing","pct":86},{"name":"Swim","pct":71},{"name":"Streetwise","pct":91},{"name":"Wilderness Survival","pct":71}]', 'Skills of note only. Climbing is printed 91%/81%, Horsemanship: General 98%/81% and Horsemanship: Exotic Animals 91%/71% (all Netherbeasts); the first figure is kept. Printed as Lore Demons & Monsters, Lore: Faeries and Math: Advanced and Basic; those carry their catalog names. Literacy in American, Atlantean, Demongogian and Splugorth has no catalog row and keeps the printed language. Also printed without a percentage: Blood Cauldron and Construct Soulmancy items, as the Soulmancer O.C.C.', 'Supernatural P.S. and P.E. Nightvision 120 feet (36.6 m), keen ordinary sight, sees the invisible and can become mist. Tracks by smell at 45%, +15% on a blood scent. Dimensional Teleport 51%; a short-range teleport of himself plus up to 300 extra pounds (135 kg), as far as five miles (8 km), at 94%. Bio-Regenerates 1D6 M.D. per melee round. Cold does half damage; toxic gases, heat and fire do none, though magic fire does half. Speaks and understands every language by magic at 98%. Shifts at will into the shape of any living creature from one foot (0.3 m) to 20 feet (6.1 m), plus shape-changing disguise and impersonation that copies a particular person and voice (Rifts Dimension Book Ten: Hades p.79). Soulmancy has made him twice the size of an ordinary Raksasha. From his Soulmancy he also has Soul Guard and the spell Damnation, as the Soulmancer O.C.C. Vulnerability as printed: arrogance and contempt for mortals. Insanity: obsessed with power and with proving himself superior, blind to what mortals can do, and drifting toward a split personality between Doom and Vicious Blade.', 'All the Soulmancy spells in this book, Soulmancy: Create Hell Pit (Ritual) among them; Soulmancy: Soul Guard and Damnation (as the Soulmancer O.C.C.). Also: Animate and Control Dead (20), Apparition (20), Aura of Death (12), Aura of Doom (40), Aura of Power (4), Armor Bizarre (15), Charismatic Aura (10), Cleanse (6), Create Magic Scroll (100), Death Trance (1), Exorcism (30), Fear (5), Fool''s Gold (10), Hallucination (30), Heal Wounds (10), Horrific Illusion (10), Illusion Booster (15), Illusion Manipulation (25+), Illusory Forest (45+), Illusory Wall (15+), Illusory Terrain (55+), Mask of Deceit (15), Multiple Image (7), Mystic Fulcrum (5), Remove Curse (140), Turn Dead (6), all Metamorphosis spells and all Protection magic. P.P.E. 700.', 'Master Psionic, I.S.P. 600: all Healing, Physical, Sensitive and Super psionic powers.', NULL, NULL, 'A black and grey duster of some supernatural creature''s hide (+300 M.D.C.) hung with five Soulmancy-animated chains, one on each arm, one at the neck and a pair at the front; each chain is 20 feet (6.1 m) long with 40 M.D.C. He directs two at a time per attack to parry or entangle, and they add no attacks. Blood Bone, a greater rune weapon of bloody bone (a dozen vertebrae and a skull) that is a rigid staff or a limp flail on command: 6D6 M.D. in either form; holds up to six souls (one is Ciro Car''bone); casts Soulmancy: Blood Bolt, Soulmancy: Blood Mist or Soulmancy: Blood Spray six times a day each at 8th level. By spending a soul it comes alive for up to 24 hours: it speaks (Horror Factor 12), moves like a snake, has four attacks, +6 to strike and dodge, 4D6 M.D. bites and tail whips, and strangles an entangled foe for 6D6 M.D. per melee. Also Techno-Wizard gear from Tolkeen, Lazlo and Stormspire, several TW vehicles among it, and a favourite modified Ley Line Skimmer with built-in weapons that can leave the ley line at half speed.', 'The whole Calgary Kingdom''s resources: about 1D4x10 million each in gold, jewels and universal credits.', 'Patient and cold, he thinks a move through before he makes it and always holds fallback plans inside his plans. A natural commander with a gift for strategy and misdirection, he chooses his fights; that restraint is often mistaken for timidity until he falls on an enemy where and when it least expects, usually with crushing numbers.', 'His troops and most of his senior commanders. Nominally Modeus, Lord of Hades, though he avoids contact for fear the Demon Lord would see through the disguise. Technically sworn to Abdul-Ra, whom he scorns and has not contacted since reaching Earth. The monsters of Calgary, whom he treats as pawns.', 'Cyber-Knights, Sky Knights and Tundra Rangers, who mean to topple Calgary and destroy its Blood Pillars; the six rival Hell Lords. Later, as the war becomes known: the Coalition States, Lazlo, Free Quebec, Lemurians, True Atlanteans, the Anti-Monsters of South America, and supernatural rivals such as the Vampires of Mexico, the Splugorth and Mrrlynn of England.', 'The Lord of Hell Pit Calgary is not who Hades thinks he is. The real Doom, a Baal-Rog risen to Prince of Hades and chosen by Modeus to lead the assault on Earth, crushed a jealous revolt among his officers, then was murdered by Vicious Blade, the Raksasha adviser who had helped him unmask it. Vicious now wears Doom''s form, a crimson, bald, winged Baal-Rog with a soul gem in its brow, while still appearing as himself, the trusted adviser rumoured to favour rebellion, so every plot against the throne is brought to him. He studies Soulmancy to finish the Hell Pit and hopes Modeus will reward the deception by naming him Earth''s Demon Lord. He commands an army called Hell''s Wrath, armed with bone weapons and demon bows and in part with Blood Energy weapons from Megaverse Armaments; it waits on reinforcements from Gamora in Hades until the Pit opens.', 'Rifts World Book 35: Megaverse in Flames p.51-54'),
('hell-lord-pain', 'Hell Lord Pain', 'Brontan Dane (true name)', 'Hell Lord, commander of Hell''s Pain', 'rifts', 'Baal-Rog (Greater Demon of Hades), mutated by Splugorth transmutation and bonded to an Eylor Slave Barge', '10th Level mutant Baal-Rog (as printed)', 10, 'Diabolic', 'Effectively Immortal, but can be slain', '15 feet (4.6 m) from belly to head; 26 feet (7.9 m) in all with the barge, which adds 11 feet (3.4 m)', '7 tons', '{"IQ":22,"ME":17,"MA":15,"PS":39,"PP":24,"PE":25,"PB":6,"Spd":20}', 105, 140, 750, 89, 220, 14, 17, '{"attacks":12,"initiative":7,"strike":7,"parry":7,"disarm":3,"entangle":3,"pull":4,"roll":4}', 'M.D.C. 750 is the upper body; each of his two tentacles has 120 (regrowing in 1D6 hours) and the barge''s main body 500. Hit Points 105, S.D.C. 140 and A.R. 14 are the block''s S.D.C.-setting figures; there the lower body has 500 S.D.C. and A.R. 17. Spd 20 is out of the barge; in it he flies at Spd 132 (90 mph/144 km), though the barge''s own section prints Spd 77 (53 mph/85 km), and both are kept here. P.P.E. 89 as printed; the Magic Knowledge line calls his base P.P.E. 46. Automatic dodge, cannot be surprised. Saves as printed: +12 vs Horror Factor, +8 vs magic, +4 vs psionics; Master Psionic. Twelve attacks include the tentacles and the Eyes of Eylor. Supernatural P.S. 39; cannot kick. W.P. Chain, Paired Weapons and Whip at 10th level, W.P. Energy Rifle and Staff at 5th. The barge''s Armor of Ithan force field: 120 M.D.C. each, four a day, a full melee between one falling and the next.', '[{"name":"Forgery","pct":71},{"name":"Gambling (Standard)","pct":98},{"name":"Gambling (Dirty Tricks)","pct":96},{"name":"Intelligence","pct":98},{"name":"Interrogation","pct":90},{"name":"Land Navigation","pct":98},{"name":"Literacy: Atlantean (Greek)","pct":98},{"name":"Literacy: Dragonese/Elven","pct":98},{"name":"Literacy: Demongogian","pct":98},{"name":"Literacy: Splugorth","pct":98},{"name":"Lore: Demons & Monsters","pct":98},{"name":"Lore: Faeries & Creatures of Magic","pct":86},{"name":"Mathematics: Basic","pct":98},{"name":"Mathematics: Advanced","pct":98},{"name":"Radio: Basic","pct":98},{"name":"Swim","pct":98},{"name":"Streetwise","pct":64},{"name":"Tracking (people)","pct":76},{"name":"Wilderness Survival","pct":96},{"name":"Prowl","pct":64}]', 'Has every Baal-Rog R.C.C. skill; these are the ones printed. Printed as Gambling, Gambling Dirty Tricks, Lore: Faeries, Math, Track (people) and Literate in Dragonese; those carry their catalog names. Atlantean (Greek), Demongogian and Splugorth literacy have no catalog row. Prowl 64% is from Silent Movement (80% below 15 mph/24 km).', 'Supernatural P.S. and P.E.; sees in the dark to 180 feet (55 m), sees the invisible, and can turn himself and the barge invisible for up to 25 minutes in any 24 hours. Tracks by smell at 70%, +20% for blood, fire and smoke, or Splugorth High Lords, Conservators and Bio-Wizards. No harm from heat, fire (M.D. magic fire and plasma included) or toxic gases. Bio-Regenerates 4D6 M.D.C. per melee; the barge mends 2 M.D.C. an hour, twice that at a nexus or in an active Hell Pit. Speaks all languages by magic. Tentacles: two, each reaching 20 feet (6.1 m), adding attacks and hitting as a punch but never a power punch; a lost tentacle regrows in 24 hours, a lost arm or hand in 48. Silent Movement: noiseless at 40 mph (64 km) or less, and can run on air up to 50 feet (15.2 m) high or across water. Lost to the mutation: Dimensional Teleport, leaping, flight and all spell casting, his Fire Whip included. Outside the barge he survives 30 seconds per P.E. point (12.5 minutes) and then dies; within 2,000 feet (610 m) he can summon it. Killed, he does not return to Hades; he is gone. Demon-slaying weapons still hurt him, but not the barge. He retreats once he or the barge is below half M.D.C.', 'None of his own. The barge supplies these spells from its 1,250 P.P.E., in any mix: Blinding Flash (1), Globe of Daylight (2), Chameleon (6; covers the barge and everyone on it), See Aura (6), See the Invisible (4), Eyes of the Wolf (25), Sense (and see) Magic (4), Sense Evil (2), Detect Concealment (6) and Ley Line Transmission (30).', 'I.S.P. 220. Equal to a 4th level Mind Melter, never improving: all Physical powers plus Bio-Manipulation (10), Clairvoyance (4), Empathy (4), Empathic Transmission (6), Intuitive Combat (10), Mentally Possess Others (30), Mind Block Auto-Defense (special), Mind Bolt (varies), Mind Wipe (special), Object Read (6), Psi-Sword (30), Presence Sense (4), Remote Viewing (10), See Aura (6), Telekinesis (Super) (10+), Telekinetic Acceleration Attack (10 or 20), Telekinetic Force Field (30), Telemechanic Paralysis (20) and Telepathy (4). The barge also grants Mind Block and Telepathy.', NULL, NULL, 'A Splugorth Pacification Staff, an Eylor staff that has bonded to him. His lower body lives inside a slightly modified Splugorth Eylor Slave Barge, a Bio-Wizard symbiote built for him and the first to carry anyone but a Splugorth Slaver; no one else can fly it. Barge: Diabolic, Horror Factor 14, magic-powered, silent (Prowl 64%), hovers to 500 feet (153 m), works underwater and in space. M.D.C. by location: Transmutation Slime Containment Chamber 250 (in the belly), barge shields none, five mounted barge eyes 50 each, five Floating Eyes of Eylor 50 each, two Barge Blasters 20 each, main body 500. Small targets need a Called Shot at -4. At zero main-body M.D.C. with its eyes alive it crawls at 10% speed with every ability off-line; destroy the body and its five eyes and it is beyond repair, and he dies in 2D6 minutes while the floating eyes fly home and the staff must find a new master within 72 hours. All of it regenerates 1D6x10 an hour at a ley line or nexus, double at a stone pyramid or active Hell Pit. Barge Blasters (2), pistol-like guns on arms at front and rear: 4D6 S.D.C. per blast (6D6 on a ley line), 2,000 feet (610 m), doubled on a ley line, each blast one of his attacks, unlimited payload. Five Floating Eyes of Eylor (Seeker-Hunter eyes): glass orbs capped in metal, Horror Factor 14, 50 M.D.C. container and 60 the eye; 20/20 sight across a wider spectrum, nightvision 600 feet (183 m), telescopic to 6,000 feet (1,829 m), x300 magnification, polarized, sun-direction 88%; see aura, the invisible, magic and P.P.E. at no cost; +5 Perception, +3 vs magic and psionics, immune to Horror Factor, gas, poison, disease and drugs; Prowl 70%, track humanoids 70%, Spd 50 (35 mph/56 km) to 400 feet (122 m). Each may cast Blinding Flash, Globe of Daylight and Chameleon (self) twice a day, and carries one combat program (roll percentile: Befuddle; Energy Bolt 4D6 S.D.C., 150 feet; Electric Arc 2D6 M.D., 240 feet; Fire Bolt, 135 feet) on 250 P.P.E., or instead a Jolt Gun in its lower cap (2D6 S.D.C., 4D6 S.D.C. or 1D4 M.D., 1,000 feet, up to four blasts a melee).', 'Plundered Splugorth goods: microbes, symbiotes and other Splugorth technology worth millions of credits, taken from outposts, scouts, Slavers and ships, Horune Pirate craft included.', 'A sadist who hurts others for the pleasure of it and keeps prisoners alive for weeks or months of torment. His fixation is making the Splugorth and everything they value suffer. Once liked, he is now obeyed out of fear and respect for his generalship; his troops never question him and keep clear of his temper.', 'Eight demons who escaped the Splugorth with him, tortured but not transformed (five Baal-Rogs, two Gallu Demon Bulls and a Demon Locust), now his guard and officers. He answers to Lord Succor-Bemoth, who covets Splugorth secrets, backs him heavily and lends mutated troops from his Hidden Army (Rifts Dimension Book 10: Hades p.220).', 'The Splugorth and all their minions above everything; Deevils a distant second.', 'A Baal-Rog who rose from the ranks on sheer fighting skill rather than ambition, captured with his troops when demons and Deevils brought their war to a Splugorth world. Bio-Wizard experiments left him with a serpent''s lower body, stunted wings, huge gorilla-like arms with sword-sized claws and a long tentacle at each side of his ribs, his lower body sealed inside an Eylor Slave Barge that keeps him alive, and cut off from Hades so that death is final. He escaped, made himself a general again, and was named one of the seven Hell Lords sent to Earth, where his true aim is to bring Atlantis down, starting with the Dimensional Market of Splynn, ahead of the Minion War itself. His army, Hell''s Pain, is named for him and shares his cruelty: a fast-churning host of conscripts that takes prisoners for torment, uses whatever weapons come to hand, favouring Splugorth, Bio-Wizard and Kittani gear, and marches under a yellow standard of a demon bone sword through an Eye of Eylor. The barge is part of this row, not a separate vehicle.', 'Rifts World Book 35: Megaverse in Flames p.56-60'),
('hell-lord-heart-ripper', 'Hell Lord Heart Ripper', 'Mencar Balraysayid (true name); also called the Devourer and the Cannibal Demon Lord', 'Hell Lord, supreme commander of the Beast Crushers', 'rifts', 'Black Jinn (Earth Elemental Magic), a Greater Demon of Hades', 'Equal to 13th level (as printed)', 13, 'Diabolic', 'Effectively Immortal', 'Man-sized up to 35 feet (10.7 m); usually 24 to 35 feet (7.3 to 10.7 m)', '10 tons at maximum size', '{"IQ":14,"ME":21,"MA":22,"PS":42,"PP":26,"PE":24,"PB":5,"Spd":50}', 315, 350, 1430, 720, 124, 14, 16, '{"attacks":8,"initiative":5,"strike":8,"parry":8,"dodge":8,"disarm":3,"entangle":3,"pull":3,"roll":3}', 'The only bonuses printed are headed Bonuses at Night (all); the block prints no daytime figures. Also +8 to dodge while flying and +7 to entangle with the tentacle. Saves: +10 vs Horror Factor, +8 vs magic, +4 vs psionics. Hit Points 315, S.D.C. 350 and A.R. 14 are the S.D.C.-setting figures; M.D.C. 1,430. Spd 50 running (35 mph/56 km), 130 flying (90 mph/144 km). Supernatural P.S. 42. W.P. Blunt, Heavy M.D. Weapons, Sword, Paired Weapons (clawed hands and feet included) and Whip. The belly maw has four attacks of its own on top of his eight. The block prints no punch or kick damage, and none is derived here.', '[{"name":"Climbing","pct":98},{"name":"Concealment","pct":80},{"name":"Dance","pct":98},{"name":"Detect Ambush","pct":90},{"name":"Gambling (Standard)","pct":98},{"name":"Gambling (Dirty Tricks)","pct":98},{"name":"Horsemanship: Exotic Animals","pct":98},{"name":"Intelligence","pct":98},{"name":"Interrogation","pct":84},{"name":"Land Navigation","pct":98},{"name":"Literacy: Dragonese/Elven","pct":98},{"name":"Literacy: Demongogian","pct":98},{"name":"Literacy: American","pct":98},{"name":"Lore: Demons & Monsters","pct":98},{"name":"Lore: Faeries & Creatures of Magic","pct":98},{"name":"Mathematics: Basic","pct":98},{"name":"Mathematics: Advanced","pct":98},{"name":"Palming","pct":90},{"name":"Pick Locks","pct":98},{"name":"Public Speaking","pct":64},{"name":"Radio: Basic","pct":84},{"name":"Swim","pct":64},{"name":"Streetwise","pct":84},{"name":"Tracking (people)","pct":74},{"name":"Wilderness Survival","pct":94}]', 'Skills of note only. Printed as Gambling, Gambling: Dirty Tricks, Lore: Faeries, Math, Track (people) and Literate in Dragonese; those carry their catalog names. Demongogian and American literacy have no catalog row.', 'Flies; Supernatural P.S. and P.E.; sharp, hawk-like sight with nightvision to 2,000 feet (610 m); sees the invisible; needs no air; can become mist, take insect form or change size. He takes half damage from fire and cold and none from toxic gases. Dimensional Teleport 87%. Heals 1D6x10 M.D.C. each melee round while he wears his healing medallion, 5D6 without it. Speaks and understands every language by magic at 98%. A Jinn is naturally invisible, but he almost never hides. Spikes run down his spine between the wings, and anyone leaping onto his back takes 1D6x10 M.D. from them; his elbows and knees are spiked as well. Belly Maw: a second, larger toothed mouth in his abdomen that acts on its own, with four attacks a melee beyond his own. Its tongue is a tentacle reaching 100 feet (30.5 m), +3 to entangle and +3 to strike as a whip, with Supernatural P.S. 30 and 100 M.D.C.; cut or destroyed, it regrows whole in 1D6+4 minutes. Vulnerabilities: those of any Jinn, plus a short fuse, impatience and a habit of charging in before looking.', 'All Earth Elemental Magic, levels 1 to 8, plus Ballistic Fire (25), Barrage (15), Fire Blast (8), Fire Globe (40), Fire Quake (160), Fuel Flame (5), Ignite Fire (6), Minor Curse (35), Meteor (75), Mystic Quake (420) and Negate Magic (30). P.P.E. 720.', 'I.S.P. 124: all Sensitive and Physical psionic powers.', NULL, NULL, 'Skull Crusher, a Diabolic rune weapon: a giant''s magic Hercules Club he swings one- or two-handed, 5D6+6 M.D., with the usual eight rune abilities and the Air Elemental powers Call Lightning, Dissipate Gases, Electrical Field, Light Blade, Miasma and Whirlwind, each six times a day. No armor; instead a bronze rune medallion engraved with the Runic word for heal, taken from a beaten foe. It is not a rune weapon and works for whoever wears it, doubling natural healing and any Bio-Regeneration (not potions or healing touch); his regeneration above already includes it.', 'Cares more for conquered people and land than treasure; usually 1D4x100,000 credits in gems and jewelry lying about his command tent, from his troops'' loot and frightened communities'' tribute.', 'Vicious through and through: he lives for battle, slaughter and conquest, and for spreading fear and misery. A sore loser who punishes his troops for his own blunders and never forgives anyone who gets the better of him. Off the field he indulges in sex, drink, gluttony and torture, likes to cripple and shame his foes, and often eats them alive; in the thick of a fight he leaves the maimed behind to die or for his minions while he goes after the stronger threat.', 'Demon Lord Charun the Cruel, who values him and has lent him troops, and secretly plans to use his army in a bid for the throne of Hades. An unusually large number of Jinn, most of them beaten or cowed into his service, and monsters who follow him from awe or fear.', 'Every minion of Dyval, dozens of Deevil generals in particular, whose assassins mostly end up as his meals. The other Hell Lords on Earth distrust him as reckless, and he sees them and most Demon Lords as rivals. Humans and D-Bees he counts as toys, slaves and fodder.', 'A Black Jinn who held the Great Rift on the Palladium World against the Deevils and has won many worlds since, some of which worship him almost as a Demon Lord. Resentful that Modeus passed him over to lead the attack on Dyval, and feared in Hades as a possible challenger, he was made a Hell Lord and sent to Earth in the hope that it would occupy or kill him. He wears the shape of a winged giant with a mouth of sword-length teeth, ember eyes weeping black, and a second gaping maw in his belly. His plan is to force the breakaway Gargoyle Empire, and perhaps the Brodkil Empire, into his ranks, then raise a Hell Pit and conquer Europe beginning with the New German Republic, Poland, the Ukraine and the Sovietski; the book expects the Gargoyles to side with the NGR rather than submit. His army, the Beast Crushers, takes its name from an early victory over Deevil Beasts in the Great Rift, fights with demon bone spears and demon bows under a blood-red banner bearing a Deevil Beast''s head on a pike, and can draw conscripts from his conquered worlds once a Hell Pit is open.', 'Rifts World Book 35: Megaverse in Flames p.62-65');
