('notable_npc', 'hell-lord-doom', 'Power punch or kick', '1D6x10 M.D.', 1, NULL, 'Counts as two melee attacks.', 2),
('notable_npc', 'hell-lord-doom', 'Blood Bone', '6D6 M.D.', 1, NULL, 'Greater rune weapon, as a staff or a flail.', 3),
('notable_npc', 'hell-lord-doom', 'Blood Bone, animated bite or tail whip', '4D6 M.D.', 1, NULL, 'Only while the weapon is animated by a spent soul; its own four attacks, +6 to strike.', 4),
('notable_npc', 'hell-lord-doom', 'Blood Bone, animated constriction', '6D6 M.D.', 1, NULL, 'Per melee, on an entangled foe, while animated.', 5),
('notable_npc', 'hell-lord-pain', 'Restrained punch', '6D6+24', 0, NULL, 'Supernatural P.S. 39, as printed.', 0),
