('notable_npc', 'hell-lord-pain', 'Claw strike', '6D6+8 M.D.', 1, NULL, NULL, 2),
('notable_npc', 'hell-lord-pain', 'Power punch', '1D6x10 M.D.', 1, NULL, 'Counts as two melee attacks.', 3),
('notable_npc', 'hell-lord-pain', 'Barge Blaster', '4D6', 0, '2,000 feet (610 m)', 'S.D.C.; 6D6 S.D.C. and double range on a ley line. Two, front and rear; each blast is one of his attacks.', 4),
('notable_npc', 'hell-lord-pain', 'Floating Eye: Energy Bolt', '4D6', 0, '150 feet (45.7 m)', 'S.D.C.; 5 P.P.E. a blast, when the eye''s combat program rolls 26-50%.', 5),
('notable_npc', 'hell-lord-pain', 'Floating Eye: Electric Arc', '2D6 M.D.', 1, '240 feet (73.2 m)', '6 P.P.E. a blast, when the eye''s combat program rolls 51-75%.', 6),
('notable_npc', 'hell-lord-pain', 'Floating Eye: Jolt Gun', '2D6 S.D.C., 4D6 S.D.C. or 1D4 M.D.', 0, '1,000 feet (305 m)', 'Optional, in place of the combat program; up to four blasts a melee; may double damage and range on a ley line.', 7),
('notable_npc', 'hell-lord-heart-ripper', 'Belly maw bite', '1D6x10 M.D.', 1, NULL, 'One of the maw''s own four attacks a melee.', 0),
('notable_npc', 'hell-lord-heart-ripper', 'Tentacle tongue strike', '5D6 M.D.', 1, '100 feet (30.5 m)', '+3 to strike like a whip, +3 to entangle.', 1),
('notable_npc', 'hell-lord-heart-ripper', 'Tentacle tongue crush', '3D6 M.D.', 1, NULL, 'Per squeeze on a wrapped victim; each squeeze is one attack.', 2),
('notable_npc', 'hell-lord-heart-ripper', 'Skull Crusher', '5D6+6 M.D.', 1, NULL, 'Rune Hercules Club, one- or two-handed.', 3);
INSERT INTO data_script_runs (filename) VALUES ('~351-megaverse-in-flames-npcs-a.sql');
